  "impact.sdg2_restaurant": "ನಿಮ್ಮ ರೆಸ್ಟೋರೆಂಟ್‌ನಿಂದ ಹೆಚ್ಚುವರಿ ಊಟವನ್ನು ಪರಿಶೀಲಿಸಿದ ಎನ್‌ಜಿಒಗಳು ಸಂಗ್ರಹಿಸಿ ದುರ್ಬಲ ಸಮುದಾಯಗಳಿಗೆ ತ್ವರಿತ, ಘನತೆಯ ಆಹಾರ ಸಹಾಯವನ್ನು ಒದಗಿಸುತ್ತವೆ, ಇದು SDG 2 ಅಡಿಯಲ್ಲಿ ಆಹಾರ ಪ್ರವೇಶವನ್ನು ವಿಸ್ತರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
  "impact.sdg2_hotel": "ಹೋಟೆಲ್ ಅಡಿಗೆಮನೆಗಳು, ಬಫೆಟ್‌ಗಳು, ಔತಣಕೂಟಗಳು ಮತ್ತು ಈವೆಂಟ್‌ಗಳಿಂದ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ನೇರವಾಗಿ ಸಮುದಾಯದ ಆಹಾರ ಪರಿಹಾರಕ್ಕೆ ರವಾನಿಸಲಾಗುತ್ತದೆ, SDG 2 ರ ಅಡಿಯಲ್ಲಿ ಆತಿಥ್ಯದ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ಪೋಷಣೆಯಾಗಿ ಪರಿವರ್ತಿಸುತ್ತದೆ.",
  "impact.sdg2_ngo": "ನಿಮ್ಮ ಸಂಸ್ಥೆಯು ದಾನ ಮಾಡಿದ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ಕುಟುಂಬಗಳು, ಮಕ್ಕಳು ಮತ್ತು ಸಹಾಯದ ಅಗತ್ಯವಿರುವ ವ್ಯಕ್ತಿಗಳಿಗೆ ತ್ವರಿತ ಊಟವಾಗಿ ಪರಿವರ್ತಿಸುತ್ತದೆ, ಇದು ನೇರವಾಗಿ SDG 2 ಗೆ ಕೊಡುಗೆ ನೀಡುತ್ತದೆ.",
  "impact.sdg2_target": "ಗುರಿ 2.1 • ವರ್ಷಪೂರ್ತಿ ಸುರಕ್ಷಿತ, ಪೌಷ್ಟಿಕ ಆಹಾರದ ಲಭ್ಯತೆ",
  "impact.sdg12_title": "ಜವಾಬ್ದಾರಿಯುತ ಬಳಕೆ ಮತ್ತು ಉತ್ಪಾದನೆ",
  "impact.sdg12_household": "ತಿನ್ನಬಹುದಾದ ಆಹಾರವು ತ್ಯಾಜ್ಯವಾಗುವುದನ್ನು ತಡೆಯುವ ಮೂಲಕ, ನಿಮ್ಮ ಕುಟುಂಬದ ದಾನವು ಜವಾಬ್ದಾರಿಯುತ ಬಳಕೆಯನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ ಮತ್ತು SDG 12 ಗೆ ಕೊಡುಗೆ ನೀಡುತ್ತದೆ.",
  "impact.sdg12_restaurant": "ದೈನಂದಿನ ಮುಕ್ತಾಯದ ಮೊದಲು ತಿನ್ನಬಹುದಾದ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ಪಟ್ಟಿ ಮಾಡುವುದು ಮತ್ತು ಮರುಹಂಚಿಕೆ ಮಾಡುವುದು ವಾಣಿಜ್ಯ ತ್ಯಾಜ್ಯವನ್ನು ತಡೆಯುತ್ತದೆ ಮತ್ತು SDG 12 ಅಡಿಯಲ್ಲಿ ಜವಾಬ್ದಾರಿಯುತ ಸಂಪನ್ಮೂಲ ನಿರ್ವಹಣೆಯನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ.",
  "impact.sdg12_hotel": "ದೊಡ್ಡ ಪ್ರಮಾಣದ ಬಫೆಟ್ ಮತ್ತು ಈವೆಂಟ್‌ನ ಹೆಚ್ಚುವರಿ ಆಹಾರದ ಜವಾಬ್ದಾರಿಯುತ ಸಮನ್ವಯ ಮತ್ತು ಸಕಾಲಿಕ ಮರುಹಂಚಿಕೆಯು ಅಪಾರ ಪ್ರಮಾಣದ ತಿನ್ನಬಹುದಾದ ಆಹಾರವು ಭೂಭರ್ತಿಗೆ ಹೋಗುವುದನ್ನು ತಡೆಯುತ್ತದೆ, ಇದು SDG 12 ಅನ್ನು ಮುನ್ನಡೆಸುತ್ತದೆ.",
  "impact.sdg12_ngo": "ದಾನ ಮಾಡಿದ ಆಹಾರವನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ ಮತ್ತು ತ್ವರಿತವಾಗಿ ವಿತರಿಸಲಾಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುವ ಮೂಲಕ, ತಿನ್ನಬಹುದಾದ ಆಹಾರವನ್ನು ತಿರಸ್ಕರಿಸುವುದನ್ನು ತಡೆಯುವಲ್ಲಿ ನಿಮ್ಮ ಸಂಸ್ಥೆಯು ಪ್ರಮುಖ ಪಾತ್ರ ವಹಿಸುತ್ತದೆ, ಇದು SDG 12 ಅನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ.",
  "impact.sdg12_target": "ಗುರಿ 12.3 • ಪ್ರತಿ ವ್ಯಕ್ತಿಯ ಆಹಾರ ತ್ಯಾಜ್ಯವನ್ನು ಅರ್ಧಕ್ಕೆ ಇಳಿಸುವುದು ಮತ್ತು ನಷ್ಟವನ್ನು ಕಡಿಮೆ ಮಾಡುವುದು",
