  "No food donations available nearby right now.": "ಪ್ರಸ್ತುತ ಹತ್ತಿರದಲ್ಲಿ ಯಾವುದೇ ಆಹಾರ ದಾನಗಳು ಲಭ್ಯವಿಲ್ಲ.",
