  "Once you claim a food listing from a restaurant, hotel, or household, volunteer coordination and handover OTPs will appear here.": "ನೀವು ರೆಸ್ಟೋರೆಂಟ್, ಹೋಟೆಲ್ ಅಥವಾ ಮನೆಯಿಂದ ಆಹಾರ ಪಟ್ಟಿಯನ್ನು ಸ್ವೀಕರಿಸಿದ ನಂತರ, ಸ್ವಯಂಸೇವಕರ ಸಮನ್ವಯ ಮತ್ತು ಹಸ್ತಾಂತರ OTP ಗಳು ಇಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "Manage your verified NGO details, contact numbers, and service coverage area.": "ನಿಮ್ಮ ಪರಿಶೀಲಿಸಿದ ಎನ್‌ಜಿಒ ವಿವರಗಳು, ಸಂಪರ್ಕ ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಸೇವಾ ವ್ಯಾಪ್ತಿಯ ಪ್ರದೇಶವನ್ನು ನಿರ್ವಹಿಸಿ.",
  "NGO registration credentials are cross-verified with official government portals before live food claims are enabled.": "ಲೈವ್ ಆಹಾರ ಕ್ಲೈಮ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವ ಮೊದಲು ಎನ್‌ಜಿಒ ನೋಂದಣಿ ವಿವರಗಳನ್ನು ಅಧಿಕೃತ ಸರ್ಕಾರಿ ಪೋರ್ಟಲ್‌ಗಳೊಂದಿಗೆ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.",
